import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    // Longest run of consecutive indices in a sorted list.
    static long longestRun(long[] a) {
        long best = 0, cur = 0;
        for (int i = 0; i < a.length; i++) {
            cur = (i > 0 && a[i] == a[i - 1] + 1) ? cur + 1 : 1;
            best = Math.max(best, cur);
        }
        return best;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        next();
        next();
        int hn = (int) next(), vn = (int) next();
