	"slices"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

// longestRun returns the longest run of consecutive indices in a sorted list.
func longestRun(a []int64) int64 {
	var best, cur int64
	for i := range a {
		if i > 0 && a[i] == a[i-1]+1 {
			cur++
		} else {
			cur = 1
		}
		best = max(best, cur)
	}
	return best
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	next()
	next()
	hn, vn := next(), next()
	h := make([]int64, hn)
	w := make([]int64, vn)
	for i := range h {
		h[i] = next()
	}
	for i := range w {
